BATCHES = {
 'B07': ['LY-009','LY-01','LY-010','LY-011','LY-012','LY-013','LY-014','LY-015','LY-016','LY-017','LY-018','LY-019','LY-021','LY-022','LY-023','LY-024','LY-025','LY-026','LY-027','LY-028'],
 'B08': ['LY-029','LY-030','LY-031','LY-032','LY-033','LY-034','LY-035','LY-036','LY-102','LY-103','LY-104','LY-105','LY-202','LY-203','LY-204','LY-205','LY-206','LY-207','LY-208','LY-210'],
 'B09': ['LY-211','LY-212','LY-215','LY-216','LY-217','LY-218','LY-219','LY-220','LY-221','LY-222','LY-227','LY-228','LY-230','LY-231','LY-232','LY-234','LY-235','LY-237','LY-240','LY-241'],
}
def tradition_line(d):
    t = d.get('tradition'); s = d.get('system')
    if t: return f'tradition: {t}（卡面 tradition＝{t}）'
    if s: return f'tradition: {s}（卡面 system＝{s}，tradition 字段未载）'
    return '卡面未标注 tradition 字段，按题面体裁自决：liuyao（六爻纳甲）'
total = 0
for b, ids in BATCHES.items():
    assert len(ids) == 20, b
    for cid in ids:
        assert cid in PRED, cid
        d = json.loads((BASE/f'inputs-dev12/{cid}.json').read_text())
        p = PRED[cid]
        basis = (tradition_line(d) + '\n'
                 + 'systems_used: liuyao（六爻纳甲）\n'
                 + p['spec'] + '\n'
                 + '应期二路复推（R61-REV1-2/-3）：初推路径与复推路径已在上文应期段/对决段逐例留痕（同点者记二路同点、异点者已按(h)与对表/对决裁决或降档）；尺度先按(k)定档再比点，无跨尺度直比。\n'
                 + '断项粒度核（R61-REV1-4）：具体断项（病位/量级/处所类）已在各例spec末行逐项记指针数与保留/降档/删去处置；方向性主断不降档（REV1-5方向锁定，复核未改终局方向）。\n'
                 + '列面—证据核（SKILL (m)指针/双闸）：已载面已在spec首段逐面处置（已断/有面无据不报/无关不报），每条保留子断均指回已载面且有盘面触发；R59-REV1条文经R60判读标失效存档，本轮只作列面留痕、不作强制闸门援引。')
        rec = dict(case_id=cid, prediction_text=p['pred'], basis=basis,
                   confidence=p['conf'], trigger=p['trigger'])
        (OUT/f'{cid}.json').write_text(json.dumps(rec, ensure_ascii=False, indent=1))
        total += 1
    print(b, 'written segment, cumulative', total)
assert total == 60
cm = sum(1 for v in PRED.values() if v['trigger']['changed_main'])
ru = sum(1 for v in PRED.values() if v['trigger']['reserve_used'])
di = sum(1 for v in PRED.values() if v['trigger']['disputed'])
print('TOTAL', total, 'changed_main', cm, 'reserve_used', ru, 'disputed', di)
